{
  "name": "SwiftClaim iOS Expense Tracker",
  "description": "An iOS-optimized web application to capture receipts, automatically recognize amounts using AI, and generate a perfectly formatted A4 claim form and attachment page.",
  "requestFramePermissions": [
    "camera"
  ]
}

export interface Receipt {
  id: string;
  originalImage: string;
  croppedImage: string | null;
  amount: number;
  category: string;
  remark: string;
  date: string;
  isManual: boolean;
  // Positioning for the attachment board
  layout: {
    x: number;
    y: number;
    width: number;
    height: number;
  };
}

export const DEFAULT_CATEGORIES = [
  "Handphone",
  "Petrol",
  "Toll",
  "Parking Fee",
  "Car Maintenance",
  "Outstation Allowance",
  "Travelling & Accomodation",
  "Transportation",
  "Staff Welfare",
  "Entertainment",
  "OT Claim",
  "Medical",
  "Misc"
];

export interface ClaimState {
  name: string;
  month: string;
  receipts: Receipt[];
  customCategories: string[];
}

import { GoogleGenAI, Type } from "@google/genai";

export async function analyzeReceipt(base64Image: string): Promise<{ amount: number; categorySuggestion: string }> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Clean the base64 string
  const data = base64Image.split(',')[1] || base64Image;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: [
        {
          parts: [
            { text: "Extract the total amount and suggest one of these categories: Handphone, Petrol, Toll, Parking Fee, Car Maintenance, Outstation Allowance, Travelling & Accomodation, Transportation, Staff Welfare, Entertainment, OT Claim, Medical, Misc. Return ONLY JSON." },
            { inlineData: { mimeType: "image/jpeg", data: data } }
          ]
        }
      ],
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            amount: { type: Type.NUMBER },
            categorySuggestion: { type: Type.STRING }
          },
          required: ["amount", "categorySuggestion"]
        }
      }
    });

    const result = JSON.parse(response.text || "{}");
    return {
      amount: result.amount || 0,
      categorySuggestion: result.categorySuggestion || "Misc"
    };
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return { amount: 0, categorySuggestion: "Misc" };
  }
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Check, X } from 'lucide-react';

interface Point {
  x: number;
  y: number;
}

interface CropToolProps {
  imageSrc: string;
  onCrop: (croppedBase64: string) => void;
  onCancel: () => void;
}

export const CropTool: React.FC<CropToolProps> = ({ imageSrc, onCrop, onCancel }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const imgRef = useRef<HTMLImageElement>(null);

  // Normalized coordinates (0-1) for the 4 corners
  const [corners, setCorners] = useState<Point[]>([
    { x: 0, y: 0 },
    { x: 1, y: 0 },
    { x: 1, y: 1 },
    { x: 0, y: 1 }
  ]);

  const [draggingIdx, setDraggingIdx] = useState<number | null>(null);

  const handlePointerMove = useCallback((e: React.PointerEvent) => {
    if (draggingIdx === null || !containerRef.current) return;

    const rect = containerRef.current.getBoundingClientRect();
    const x = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    const y = Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height));

    setCorners(prev => {
      const next = [...prev];
      next[draggingIdx] = { x, y };
      return next;
    });
  }, [draggingIdx]);

  const handlePointerUp = () => setDraggingIdx(null);

  const performCrop = () => {
    if (!imgRef.current) return;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const img = imgRef.current;

    // For simplicity, we'll do a rectangular crop based on the bounds of the 4 points
    const minX = Math.min(...corners.map(c => c.x)) * img.naturalWidth;
    const maxX = Math.max(...corners.map(c => c.x)) * img.naturalWidth;
    const minY = Math.min(...corners.map(c => c.y)) * img.naturalHeight;
    const maxY = Math.max(...corners.map(c => c.y)) * img.naturalHeight;

    const width = maxX - minX;
    const height = maxY - minY;

    canvas.width = width;
    canvas.height = height;

    ctx.drawImage(img, minX, minY, width, height, 0, 0, width, height);
    onCrop(canvas.toDataURL('image/jpeg', 0.8));
  };

  return (
    <div className="fixed inset-0 z-50 bg-black/90 flex flex-col items-center justify-center p-4">
      <div className="w-full max-w-lg flex flex-col gap-4">
        <div className="flex justify-between items-center text-white">
          <h2 className="text-xl font-bold">Crop Receipt</h2>
          <button onClick={onCancel} className="p-2 bg-white/10 rounded-full hover:bg-white/20 transition">
            <X size={24} />
          </button>
        </div>

        <div 
          ref={containerRef}
          className="relative w-full aspect-[3/4] bg-slate-800 rounded-lg overflow-hidden touch-none"
          onPointerMove={handlePointerMove}
          onPointerUp={handlePointerUp}
          onPointerLeave={handlePointerUp}
        >
          <img 
            ref={imgRef}
            src={imageSrc} 
            className="w-full h-full object-contain pointer-events-none select-none"
            alt="To crop"
          />

          {/* Overlay Grid */}
          <div className="absolute inset-0 pointer-events-none">
             <svg className="w-full h-full">
                <polygon 
                  points={corners.map(c => `${c.x * 100}%,${c.y * 100}%`).join(' ')} 
                  className="fill-blue-500/20 stroke-blue-400 stroke-2"
                />
             </svg>
          </div>

          {/* Draggable Corners */}
          {corners.map((p, i) => (
            <div
              key={i}
              onPointerDown={(e) => {
                e.preventDefault();
                setDraggingIdx(i);
              }}
              style={{ left: `${p.x * 100}%`, top: `${p.y * 100}%` }}
              className="absolute w-8 h-8 -ml-4 -mt-4 bg-white border-4 border-blue-500 rounded-full shadow-lg cursor-pointer z-10 flex items-center justify-center"
            >
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full" />
            </div>
          ))}
        </div>

        <button
          onClick={performCrop}
          className="w-full py-4 bg-blue-600 hover:bg-blue-700 text-white font-bold rounded-xl flex items-center justify-center gap-2 shadow-xl active:scale-95 transition"
        >
          <Check size={20} />
          Apply Selection
        </button>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { Receipt } from '../types';
import { Move, Maximize2 } from 'lucide-react';

interface AttachmentBoardProps {
  receipts: Receipt[];
  onUpdateReceipt: (id: string, layout: Receipt['layout']) => void;
  isPrintView?: boolean;
}

export const AttachmentBoard: React.FC<AttachmentBoardProps> = ({ receipts, onUpdateReceipt, isPrintView = false }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [activeId, setActiveId] = useState<string | null>(null);
  const [dragMode, setDragMode] = useState<'move' | 'resize' | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialLayout, setInitialLayout] = useState<Receipt['layout'] | null>(null);

  const filteredReceipts = receipts.filter(r => !!r.croppedImage);

  const handlePointerDown = (id: string, mode: 'move' | 'resize', e: React.PointerEvent) => {
    if (isPrintView) return;
    setActiveId(id);
    setDragMode(mode);
    setStartPos({ x: e.clientX, y: e.clientY });
    const receipt = receipts.find(r => r.id === id);
    if (receipt) setInitialLayout({ ...receipt.layout });
  };

  useEffect(() => {
    const handlePointerMove = (e: PointerEvent) => {
      if (!activeId || !dragMode || !initialLayout || !containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const dx = ((e.clientX - startPos.x) / rect.width) * 100;
      const dy = ((e.clientY - startPos.y) / rect.height) * 100;

      const newLayout = { ...initialLayout };

      if (dragMode === 'move') {
        newLayout.x = Math.max(0, Math.min(100 - initialLayout.width, initialLayout.x + dx));
        newLayout.y = Math.max(0, Math.min(100 - initialLayout.height, initialLayout.y + dy));
      } else if (dragMode === 'resize') {
        newLayout.width = Math.max(10, initialLayout.width + dx);
        newLayout.height = Math.max(10, initialLayout.height + dy);
      }

      onUpdateReceipt(activeId, newLayout);
    };

    const handlePointerUp = () => {
      setActiveId(null);
      setDragMode(null);
    };

    if (activeId) {
      window.addEventListener('pointermove', handlePointerMove);
      window.addEventListener('pointerup', handlePointerUp);
    }

    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
    };
  }, [activeId, dragMode, initialLayout, startPos, onUpdateReceipt]);

  return (
    <div 
      ref={containerRef}
      className={`relative a4-preview ${isPrintView ? 'print-page' : 'mx-auto'}`}
    >
      <div className="absolute top-4 left-4 text-slate-300 font-bold text-2xl uppercase pointer-events-none">
        Attachments
      </div>

      {filteredReceipts.map((r) => (
        <div
          key={r.id}
          className={`absolute border border-slate-200 bg-white group select-none ${activeId === r.id ? 'z-20 ring-2 ring-blue-500' : 'z-10'}`}
          style={{
            left: `${r.layout.x}%`,
            top: `${r.layout.y}%`,
            width: `${r.layout.width}%`,
            height: `${r.layout.height}%`,
            touchAction: 'none'
          }}
        >
          <img 
            src={r.croppedImage!} 
            className="w-full h-full object-contain pointer-events-none" 
            alt="Receipt"
          />

          {!isPrintView && (
            <>
              {/* Move Handle */}
              <div 
                className="absolute inset-0 cursor-move flex items-center justify-center opacity-0 group-hover:opacity-100 bg-black/5 transition"
                onPointerDown={(e) => handlePointerDown(r.id, 'move', e)}
              >
                <Move className="text-blue-500 bg-white p-1 rounded-full shadow-lg" size={32} />
              </div>

              {/* Resize Handle (Bottom Right) */}
              <div 
                className="absolute bottom-0 right-0 w-8 h-8 bg-blue-500 cursor-nwse-resize flex items-center justify-center rounded-tl-lg shadow-lg"
                onPointerDown={(e) => {
                  e.stopPropagation();
                  handlePointerDown(r.id, 'resize', e);
                }}
              >
                <Maximize2 size={16} className="text-white" />
              </div>
            </>
          )}
        </div>
      ))}
    </div>
  );
};

import React from 'react';
import { ClaimState, DEFAULT_CATEGORIES } from '../types';

interface ClaimFormProps {
  state: ClaimState;
}

export const ClaimForm: React.FC<ClaimFormProps> = ({ state }) => {
  const allCategories = [...DEFAULT_CATEGORIES, ...state.customCategories];

  const categorySummary = allCategories.map((cat, index) => {
    const relevantReceipts = state.receipts.filter(r => r.category === cat);
    const totalAmount = relevantReceipts.reduce((sum, r) => sum + r.amount, 0);
    const remarks = relevantReceipts.map(r => r.remark).filter(rem => rem.trim() !== "").join(', ');

    return {
      index: index + 1,
      name: cat,
      amount: totalAmount,
      description: remarks ? `(${remarks})` : ""
    };
  });

  const totalClaim = categorySummary.reduce((sum, item) => sum + item.amount, 0);

  return (
    <div className="a4-preview print-page p-8 text-[12px] font-sans flex flex-col">
      <div className="text-center mb-6">
        <h1 className="text-base font-bold uppercase tracking-widest">Elcomp Technologies Sdn Bhd (589723-U)</h1>
        <h2 className="text-sm font-bold mt-2 underline">STAFF MONTHLY CLAIM FORM</h2>
      </div>

      <div className="flex justify-between mb-8">
        <div className="flex items-center gap-2">
          <span className="font-bold">Name:</span>
          <span className="border-b border-black min-w-[200px] pb-0.5">{state.name}</span>
        </div>
        <div className="flex items-center gap-2">
          <span className="font-bold">Month:</span>
          <span className="border-b border-black min-w-[150px] pb-0.5">{state.month}</span>
        </div>
      </div>

      <table className="w-full border-collapse border border-black mb-10">
        <thead>
          <tr className="bg-slate-50">
            <th className="border border-black px-2 py-1 w-12">Items</th>
            <th className="border border-black px-2 py-1 text-left">Descriptions</th>
            <th className="border border-black px-2 py-1 w-32 text-right">Amount (RM)</th>
          </tr>
        </thead>
        <tbody>
          {categorySummary.map((item) => (
            <tr key={item.index} className="h-7">
              <td className="border border-black text-center">{item.index}</td>
              <td className="border border-black px-2 py-1">
                {item.name} <span className="text-slate-500 italic ml-1">{item.description}</span>
              </td>
              <td className="border border-black px-2 py-1 text-right">
                {item.amount > 0 ? item.amount.toFixed(2) : ""}
              </td>
            </tr>
          ))}
          {/* Pad to 20 rows if needed */}
          {Array.from({ length: Math.max(0, 15 - categorySummary.length) }).map((_, i) => (
            <tr key={`pad-${i}`} className="h-7">
              <td className="border border-black text-center">{categorySummary.length + i + 1}</td>
              <td className="border border-black px-2 py-1"></td>
              <td className="border border-black px-2 py-1 text-right"></td>
            </tr>
          ))}
          <tr className="font-bold h-10">
            <td className="border border-black"></td>
            <td className="border border-black px-2 py-1 text-right">Total:</td>
            <td className="border border-black px-2 py-1 text-right">{totalClaim.toFixed(2)}</td>
          </tr>
        </tbody>
      </table>

      <div className="mt-auto flex justify-between items-end pb-10">
        <div className="text-center w-64">
          <div className="border-t border-black pt-2">Claimed By:</div>
        </div>
        <div className="text-center w-64">
          <div className="border-t border-black pt-2">Authorised By:</div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef } from 'react';
import { Camera, Upload, Plus, Trash2, Printer, ChevronLeft, ChevronRight, Wand2, FileText, Layout, X, Loader2 } from 'lucide-react';
import { Receipt, ClaimState, DEFAULT_CATEGORIES } from './types';
import { analyzeReceipt } from './services/geminiService';
import { CropTool } from './components/CropTool';
import { ClaimForm } from './components/ClaimForm';
import { AttachmentBoard } from './components/AttachmentBoard';

const App: React.FC = () => {
  const [state, setState] = useState<ClaimState>({
    name: '',
    month: new Date().toLocaleString('default', { month: 'long', year: 'numeric' }),
    receipts: [],
    customCategories: []
  });

  const [activeStep, setActiveStep] = useState<'dashboard' | 'preview'>('dashboard');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [rawImageToCrop, setRawImageToCrop] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('swiftclaim_state');
    if (saved) setState(JSON.parse(saved));
  }, []);

  useEffect(() => {
    localStorage.setItem('swiftclaim_state', JSON.stringify(state));
  }, [state]);

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (re) => {
        setRawImageToCrop(re.target?.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleManualAdd = () => {
    const newReceipt: Receipt = {
      id: Math.random().toString(36).substr(2, 9),
      originalImage: '',
      croppedImage: null,
      amount: 0,
      category: 'Misc',
      remark: '',
      date: new Date().toISOString().split('T')[0],
      isManual: true,
      layout: { x: 5, y: 5, width: 25, height: 25 }
    };
    setState(prev => ({ ...prev, receipts: [...prev.receipts, newReceipt] }));
  };

  const finalizeReceipt = async (croppedBase64: string) => {
    setRawImageToCrop(null);
    setIsAnalyzing(true);

    try {
      const { amount, categorySuggestion } = await analyzeReceipt(croppedBase64);

      const newReceipt: Receipt = {
        id: Math.random().toString(36).substr(2, 9),
        originalImage: croppedBase64, // using cropped as primary
        croppedImage: croppedBase64,
        amount: amount || 0,
        category: categorySuggestion || 'Misc',
        remark: '',
        date: new Date().toISOString().split('T')[0],
        isManual: false,
        layout: { 
          x: (state.receipts.length * 5) % 70, 
          y: (state.receipts.length * 10) % 70, 
          width: 30, 
          height: 30 
        }
      };

      setState(prev => ({ ...prev, receipts: [...prev.receipts, newReceipt] }));
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const updateReceipt = (id: string, updates: Partial<Receipt>) => {
    setState(prev => ({
      ...prev,
      receipts: prev.receipts.map(r => r.id === id ? { ...r, ...updates } : r)
    }));
  };

  const updateLayout = (id: string, layout: Receipt['layout']) => {
    updateReceipt(id, { layout });
  };

  const removeReceipt = (id: string) => {
    setState(prev => ({
      ...prev,
      receipts: prev.receipts.filter(r => r.id !== id)
    }));
  };

  const handleAddCustomCategory = () => {
    const name = prompt("Enter new category name:");
    if (name && !DEFAULT_CATEGORIES.includes(name) && !state.customCategories.includes(name)) {
      setState(prev => ({ ...prev, customCategories: [...prev.customCategories, name] }));
    }
  };

  return (
    <div className="max-w-2xl mx-auto min-h-screen bg-slate-50 flex flex-col p-4">
      {/* Header */}
      <header className="flex items-center justify-between mb-8 pt-6">
        <div>
          <h1 className="text-3xl font-extrabold text-blue-600 tracking-tight">SwiftClaim</h1>
          <p className="text-slate-500 font-medium">Monthly Expense Formatter</p>
        </div>
        {activeStep === 'dashboard' ? (
          <button 
            onClick={() => setActiveStep('preview')}
            disabled={state.receipts.length === 0}
            className="flex flex-col items-center justify-center p-3 bg-white shadow-sm border border-slate-200 rounded-2xl hover:border-blue-500 disabled:opacity-50 transition"
          >
            <Printer className="text-blue-600 mb-1" size={24} />
            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Print Preview</span>
          </button>
        ) : (
          <button 
            onClick={() => setActiveStep('dashboard')}
            className="flex flex-col items-center justify-center p-3 bg-white shadow-sm border border-slate-200 rounded-2xl hover:border-blue-500 transition"
          >
            <Layout className="text-blue-600 mb-1" size={24} />
            <span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">Dashboard</span>
          </button>
        )}
      </header>

      {activeStep === 'dashboard' ? (
        <>
          {/* Form Header Info */}
          <div className="grid grid-cols-2 gap-4 mb-8">
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 block">Staff Name</label>
              <input 
                type="text" 
                value={state.name}
                onChange={(e) => setState(prev => ({ ...prev, name: e.target.value }))}
                placeholder="Required"
                className="w-full bg-transparent font-bold text-lg outline-none focus:text-blue-600 transition"
              />
            </div>
            <div className="bg-white p-4 rounded-2xl shadow-sm border border-slate-100">
              <label className="text-xs font-bold text-slate-400 uppercase tracking-widest mb-1 block">Month</label>
              <input 
                type="text" 
                value={state.month}
                onChange={(e) => setState(prev => ({ ...prev, month: e.target.value }))}
                className="w-full bg-transparent font-bold text-lg outline-none focus:text-blue-600 transition"
              />
            </div>
          </div>

          {/* Action Cards */}
          <div className="grid grid-cols-3 gap-3 mb-10">
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="flex flex-col items-center justify-center gap-3 p-6 bg-blue-600 rounded-3xl text-white shadow-xl shadow-blue-200 active:scale-95 transition"
            >
              <div className="p-2 bg-white/20 rounded-xl">
                <Camera size={28} />
              </div>
              <span className="font-bold text-sm">Capture</span>
            </button>
            <button 
              onClick={handleManualAdd}
              className="flex flex-col items-center justify-center gap-3 p-6 bg-white border-2 border-slate-200 rounded-3xl text-slate-700 active:scale-95 transition"
            >
              <div className="p-2 bg-slate-100 rounded-xl">
                <Plus size={28} />
              </div>
              <span className="font-bold text-sm">Manual</span>
            </button>
            <button 
              onClick={handleAddCustomCategory}
              className="flex flex-col items-center justify-center gap-3 p-6 bg-slate-100 rounded-3xl text-slate-600 active:scale-95 transition"
            >
              <div className="p-2 bg-slate-200 rounded-xl">
                <Layout size={28} />
              </div>
              <span className="font-bold text-sm">Category</span>
            </button>
          </div>

          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileUpload} 
            accept="image/*" 
            capture="environment" 
            className="hidden" 
          />

          {/* Receipts List */}
          <div className="space-y-4 pb-24">
            <h3 className="text-sm font-bold text-slate-400 uppercase tracking-widest px-1">Claims ({state.receipts.length})</h3>

            {isAnalyzing && (
              <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100 flex items-center justify-center gap-4 text-blue-600 animate-pulse">
                <Loader2 className="animate-spin" />
                <span className="font-bold">AI analyzing receipt...</span>
              </div>
            )}

            {state.receipts.length === 0 && !isAnalyzing && (
              <div className="bg-slate-100 p-12 rounded-3xl text-center border-2 border-dashed border-slate-200">
                <FileText className="mx-auto text-slate-300 mb-3" size={48} />
                <p className="text-slate-400 font-medium">No claims added yet.<br/>Start by capturing a receipt.</p>
              </div>
            )}

            {state.receipts.map(receipt => (
              <div key={receipt.id} className="bg-white p-4 rounded-3xl shadow-sm border border-slate-100 flex gap-4 items-start group">
                {receipt.croppedImage ? (
                  <div className="w-20 h-20 bg-slate-100 rounded-2xl overflow-hidden shrink-0">
                    <img src={receipt.croppedImage} className="w-full h-full object-cover" alt="Receipt thumbnail" />
                  </div>
                ) : (
                  <div className="w-20 h-20 bg-slate-50 border-2 border-dashed border-slate-200 rounded-2xl flex items-center justify-center shrink-0">
                    <Plus className="text-slate-300" />
                  </div>
                )}

                <div className="flex-1 space-y-2">
                  <div className="flex justify-between items-start">
                    <select 
                      value={receipt.category}
                      onChange={(e) => updateReceipt(receipt.id, { category: e.target.value })}
                      className="text-xs font-bold uppercase tracking-wider text-blue-600 bg-blue-50 px-2 py-1 rounded-md outline-none border-none cursor-pointer"
