  const handleReset = () => {
    if (confirm("Are you sure you want to reset? All local data will be permanently cleared.")) {
      localStorage.removeItem('swiftclaim_state');
      setState({
        name: '',
        month: new Date().toLocaleString('default', { month: 'long', year: 'numeric' }),
        receipts: [],
