                className={`px-4 py-1.5 rounded-md text-sm font-medium transition ${activeStep === 'preview' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:text-slate-700 disabled:opacity-50'}`}
              >
