          {/* AI Loader */}
          {isAnalyzing && (
            <div className="mb-6 bg-blue-50 border border-blue-100 p-4 rounded-xl flex items-center justify-center gap-3 text-blue-700 animate-pulse">
              <Loader2 className="animate-spin" size={20} />
